<script>
    var otherSkillCounter = 0; // Initialize counter for naming

    function OtherSkills() {

        var inputOtherSkill = document.getElementById('otherSkills').value.toUpperCase();

        for (var i = 1; i <= 16; i++) {
            if (document.getElementById('skill' + i).value === inputOtherSkill) {
                console.log('Duplicate skill detected:', inputOtherSkill);
                window.dispatchEvent(new CustomEvent('open-modal', {
                    detail: 'duplicate-skills-modal' // Assuming $name holds the modal name
                }));
                return; // Exit the function if the skill already exists
            }
        }



        function printHiddenInputs() {
            var hiddenInputs = document.querySelectorAll('input[type="hidden"]');
            for (var i = 0; i < hiddenInputs.length; i++) {
                var input = hiddenInputs[i];
                console.log('Hidden input ' + i + ':', input.name, '=', input.value);
            }
        }

        // Check if the skill already exists
        var existingSkills = document.querySelectorAll('input[name^="otherSkillPost"]');
        for (var i = 0; i < existingSkills.length; i++) {
            if (existingSkills[i].value === inputOtherSkill) {
                console.log('Duplicate skill detected:', inputOtherSkill);
                window.dispatchEvent(new CustomEvent('open-modal', {
                    detail: 'duplicate-skills-modal' // Assuming $name holds the modal name
                }));
                return; // Exit the function if the skill already exists
            }
        }


        var skillBadge = `<span class="inline-flex items-center mr-1 mt-1 gap-x-1.5 py-1.5 ps-3 pe-2 rounded-full text-xs font-medium bg-blue-100 text-blue-800 dark:bg-blue-800/30 dark:text-blue-500">
        ${inputOtherSkill}
        <button type="button" onclick="removeBadge(this)" class="flex-shrink-0 size-4 inline-flex items-center justify-center rounded-full hover:bg-blue-200 focus:outline-none focus:bg-blue-200 focus:text-blue-500 dark:hover:bg-blue-900">
            <span class="sr-only">Remove badge</span>
            <svg class="flex-shrink-0 size-3" xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <path d="M18 6 6 18" />
                <path d="m6 6 12 12" />
            </svg>
        </button>
        <input type="hidden" name="otherSkillPost[${otherSkillCounter++}]" value="${inputOtherSkill}" id="hiddenOtherSkills">
    </span>`;

        $('#otherSkillRow').append(skillBadge);


        // Update hidden input array
        // var hiddenInput = document.getElementById('hiddenOtherSkills');
        // hiddenInput.outerHTML =
        //     ``;

        printHiddenInputs();
        // console.log('Updated hidden input:', hiddenInput.outerHTML);

    }

    function removeBadge(button) {

        var span = $(button).parent();
        var skillText = span.text().trim();

        // Remove the badge from HTML
        span.remove();
        console.log('Badge removed from HTML:', skillText);

        // Remove the corresponding hidden input elements
        $('input[name^="otherSkillPost"]').each(function() {
            if ($(this).val() === skillText) {
                $(this).remove();
                console.log('Hidden input removed:', $(this).attr('name') + ' = ' + $(this).val());
            }
        });

    }
</script>
